import React, { useState, useEffect } from 'react';
import { Card, Button, Select, Alert, api, Badge } from '../App';

export default function MarkingPage() {
  const [parties,  setParties]  = useState([]);
  const [saleNos,  setSaleNos]  = useState([]);
  const [grades,   setGrades]   = useState([]);
  const [brokers,  setBrokers]  = useState([]);
  const [gardens,  setGardens]  = useState([]);

  // Filters
  const [partyId,   setPartyId]   = useState('');
  const [partyCode, setPartyCode] = useState('');
  const [saleNo,    setSaleNo]    = useState('');
  const [selGrades, setSelGrades] = useState([]);
  const [selGardens,setSelGardens]= useState([]);
  const [priceMin,  setPriceMin]  = useState('');
  const [priceMax,  setPriceMax]  = useState('');
  const [broker,    setBroker]    = useState('');
  const [dateFrom,  setDateFrom]  = useState('');
  const [dateTo,    setDateTo]    = useState('');
  const [bagsMin,   setBagsMin]   = useState('');
  const [bagsMax,   setBagsMax]   = useState('');
  const [wtMin,     setWtMin]     = useState('');
  const [wtMax,     setWtMax]     = useState('');
  const [maxMark,   setMaxMark]   = useState('');
  const [skipBlank, setSkipBlank] = useState(true);
  const [aiWeeks,   setAiWeeks]   = useState('2');

  const [preview,  setPreview]  = useState([]);
  const [loading,  setLoading]  = useState(false);
  const [aiLoading,setAiLoading]= useState(false);
  const [saving,   setSaving]   = useState(false);
  const [alert,    setAlert]    = useState(null);
  const [prices,   setPrices]   = useState({});
  const [skipped,  setSkipped]  = useState({});
  const [aiInfo,   setAiInfo]   = useState(null);
  const [showFilters, setShowFilters] = useState(true);

  useEffect(() => {
    Promise.all([
      api.get('/parties').catch(()=>({data:[]})),
      api.get('/import/sale-numbers').catch(()=>({data:[]})),
      api.get('/marking/grades/list').catch(()=>({data:[]})),
      api.get('/marking/brokers/list').catch(()=>({data:[]})),
      api.get('/mapping/gardens').catch(()=>({data:[]}))
    ]).then(([p,s,g,b,gd]) => {
      setParties(p.data);
      setSaleNos(s.data);
      setGrades(g.data);
      setBrokers(b.data);
      setGardens(gd.data);
    });
  }, []);

  const handlePartyChange = (id) => {
    setPartyId(id);
    const p = parties.find(x => x.id === id);
    setPartyCode(p?.party_code || '');
  };

  const runPreview = async () => {
    if (!partyId || !saleNo) { setAlert({ msg:'Select party and sale number first', type:'error' }); return; }
    setLoading(true); setAlert(null); setAiInfo(null);
    try {
      const r = await api.post('/marking/preview', {
        party_id:           partyId,
        sale_no:            saleNo,
        grades:             selGrades,
        gardens:            selGardens,
        price_min:          priceMin  ? parseFloat(priceMin)  : undefined,
        price_max:          priceMax  ? parseFloat(priceMax)  : undefined,
        broker:             broker    || undefined,
        date_from:          dateFrom  || undefined,
        date_to:            dateTo    || undefined,
        bags_min:           bagsMin   ? parseInt(bagsMin)     : undefined,
        bags_max:           bagsMax   ? parseInt(bagsMax)     : undefined,
        wt_min:             wtMin     ? parseFloat(wtMin)     : undefined,
        wt_max:             wtMax     ? parseFloat(wtMax)     : undefined,
        max_mark_space:     maxMark   ? parseInt(maxMark)     : undefined,
        skip_no_last_price: skipBlank,
      });
      setPreview(r.data);
      const init = {};
      r.data.forEach(row => { init[row.catalogue_id] = row.suggested_price || ''; });
      setPrices(init); setSkipped({});
      if (r.data.length === 0) setAlert({ msg:'No lots found. Try relaxing the filters or check the party mapping.', type:'warning' });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type:'error' }); }
    finally { setLoading(false); }
  };

  const runAI = async () => {
    if (!partyId || !saleNo) return;
    setAiLoading(true); setAiInfo(null);
    try {
      const r = await api.post('/ai/suggest', { party_id: partyId, sale_no: saleNo, weeks: parseInt(aiWeeks) });
      if (r.data.suggestions?.length > 0) {
        const np = { ...prices };
        let applied = 0;
        r.data.suggestions.forEach(s => {
          const match = preview.find(p => p.garden === s.garden && p.grade === s.grade && p.mark === s.mark);
          if (match && s.suggested_price) { np[match.catalogue_id] = Number(s.suggested_price).toFixed(2); applied++; }
        });
        setPrices(np);
        setAiInfo({ method: r.data.method, weeks: r.data.history_weeks, count: applied, history: r.data.history_count });
      } else {
        setAlert({ msg: `AI found no history data for this party in the last ${aiWeeks} weeks. Using catalogue last sale prices instead.`, type:'warning' });
      }
    } catch (e) { setAlert({ msg:'AI suggestion failed: ' + e.message, type:'error' }); }
    finally { setAiLoading(false); }
  };

  const save = async () => {
    const markings = preview.filter(row => !skipped[row.catalogue_id]).map(row => ({
      party_id: partyId, party_name: row.party_name, party_code: partyCode,
      garden: row.garden, grade: row.grade, mark: row.mark,
      bags: row.bags, net_wt: row.net_wt, broker: row.broker,
      sale_no: saleNo, price_min: priceMin || undefined, price_max: priceMax || undefined,
      max_mark_space: maxMark || undefined,
      suggested_price: row.suggested_price,
      final_price: prices[row.catalogue_id] || row.suggested_price,
      status: 'confirmed', ai_suggested: !!aiInfo
    }));
    if (markings.length === 0) { setAlert({ msg:'No markings to save', type:'warning' }); return; }
    setSaving(true);
    try {
      const r = await api.post('/marking/save', { markings, sale_no: saleNo });
      setAlert({ msg:`✅ ${r.data.saved} markings saved for Sale #${saleNo}. Go to Labels to print.`, type:'success' });
      setPreview([]); setAiInfo(null);
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type:'error' }); }
    finally { setSaving(false); }
  };

  const toggleGrade  = (g) => setSelGrades(p  => p.includes(g) ? p.filter(x=>x!==g) : [...p, g]);
  const toggleGarden = (g) => setSelGardens(p => p.includes(g) ? p.filter(x=>x!==g) : [...p, g]);
  const toggleSkip   = (id) => setSkipped(s => ({ ...s, [id]: !s[id] }));

  const activeCount = preview.filter(r => !skipped[r.catalogue_id]).length;
  const skipCount   = Object.values(skipped).filter(Boolean).length;
  const fmt = v => v !== null && v !== undefined ? Number(v).toFixed(2) : '—';

  return (
    <div>
      <h2 style={{ marginBottom:4, color:'#1a3c5e' }}>✅ Create Markings</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>Apply filters, get AI price suggestions based on 2 or 4 weeks history, then save markings.</p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      {/* FILTER PANEL */}
      <Card>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14 }}>
          <h3 style={{ fontSize:15 }}>⚙️ Filters</h3>
          <button onClick={() => setShowFilters(!showFilters)} style={{ background:'none', border:'none', cursor:'pointer', color:'#888', fontSize:13 }}>
            {showFilters ? '▲ Hide' : '▼ Show'}
          </button>
        </div>

        {showFilters && <>
          {/* Row 1: Party, Party Code, Sale No, Broker */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:12, marginBottom:12 }}>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Party Name *</label>
              <select value={partyId} onChange={e => handlePartyChange(e.target.value)}
                style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }}>
                <option value="">Select party…</option>
                {parties.map(p => <option key={p.id} value={p.id}>{p.party_name}</option>)}
              </select>
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Party Code</label>
              <input value={partyCode} readOnly placeholder="Auto-filled"
                style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13, background:'#f8fafc', color:'#888' }} />
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Sale Number *</label>
              <select value={saleNo} onChange={e => setSaleNo(e.target.value)}
                style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }}>
                <option value="">Select sale…</option>
                {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no}{s.week_date ? ' ('+new Date(s.week_date).toLocaleDateString('en-IN')+')' : ''}</option>)}
              </select>
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Broker</label>
              <select value={broker} onChange={e => setBroker(e.target.value)}
                style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }}>
                <option value="">All Brokers</option>
                {brokers.map(b => <option key={b} value={b}>{b}</option>)}
              </select>
            </div>
          </div>

          {/* Row 2: Price Bracket, Max Mark Space, Bags, Net Wt */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:12, marginBottom:12 }}>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Price Bracket (₹)</label>
              <div style={{ display:'flex', gap:6 }}>
                <input value={priceMin} onChange={e => setPriceMin(e.target.value)} type="number" placeholder="Min"
                  style={{ width:'50%', padding:'8px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
                <input value={priceMax} onChange={e => setPriceMax(e.target.value)} type="number" placeholder="Max"
                  style={{ width:'50%', padding:'8px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
              </div>
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Max Mark Space (bags)</label>
              <input value={maxMark} onChange={e => setMaxMark(e.target.value)} type="number" placeholder="e.g. 50"
                style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Bags (min–max)</label>
              <div style={{ display:'flex', gap:6 }}>
                <input value={bagsMin} onChange={e => setBagsMin(e.target.value)} type="number" placeholder="Min"
                  style={{ width:'50%', padding:'8px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
                <input value={bagsMax} onChange={e => setBagsMax(e.target.value)} type="number" placeholder="Max"
                  style={{ width:'50%', padding:'8px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
              </div>
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Net Wt (min–max kg)</label>
              <div style={{ display:'flex', gap:6 }}>
                <input value={wtMin} onChange={e => setWtMin(e.target.value)} type="number" placeholder="Min"
                  style={{ width:'50%', padding:'8px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
                <input value={wtMax} onChange={e => setWtMax(e.target.value)} type="number" placeholder="Max"
                  style={{ width:'50%', padding:'8px 8px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
              </div>
            </div>
          </div>

          {/* Row 3: Date range */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:12, marginBottom:14 }}>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Date From</label>
              <input value={dateFrom} onChange={e => setDateFrom(e.target.value)} type="date"
                style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#555', marginBottom:4, textTransform:'uppercase', letterSpacing:0.4 }}>Date To</label>
              <input value={dateTo} onChange={e => setDateTo(e.target.value)} type="date"
                style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }} />
            </div>
          </div>

          {/* Grade filter */}
          <div style={{ marginBottom:12 }}>
            <div style={{ fontSize:11, fontWeight:700, color:'#555', marginBottom:6, textTransform:'uppercase', letterSpacing:0.4 }}>Grade Filter</div>
            <div style={{ display:'flex', gap:6, flexWrap:'wrap' }}>
              {grades.map(g => (
                <span key={g} onClick={() => toggleGrade(g)}
                  style={{ padding:'4px 12px', borderRadius:20, fontSize:12, fontWeight:600, cursor:'pointer', userSelect:'none',
                    background: selGrades.includes(g) ? '#1a3c5e' : '#f0f4f8',
                    color:      selGrades.includes(g) ? '#fff'     : '#555',
                    border:     `1.5px solid ${selGrades.includes(g) ? '#1a3c5e' : '#e2e8f0'}` }}>
                  {g}
                </span>
              ))}
              {selGrades.length > 0 && (
                <span onClick={() => setSelGrades([])} style={{ padding:'4px 12px', borderRadius:20, fontSize:12, cursor:'pointer', color:'#c0392b', border:'1.5px solid #c0392b' }}>✕ Clear</span>
              )}
            </div>
          </div>

          {/* Garden filter */}
          <div style={{ marginBottom:14 }}>
            <div style={{ fontSize:11, fontWeight:700, color:'#555', marginBottom:6, textTransform:'uppercase', letterSpacing:0.4 }}>Garden Filter</div>
            <div style={{ display:'flex', gap:6, flexWrap:'wrap', maxHeight:120, overflowY:'auto', padding:'4px 0' }}>
              {gardens.map(g => (
                <span key={g} onClick={() => toggleGarden(g)}
                  style={{ padding:'3px 10px', borderRadius:20, fontSize:11, fontWeight:600, cursor:'pointer', userSelect:'none',
                    background: selGardens.includes(g) ? '#dcfce7' : '#f9fafb',
                    color:      selGardens.includes(g) ? '#166534' : '#555',
                    border:     `1.5px solid ${selGardens.includes(g) ? '#1a7a4a' : '#e2e8f0'}` }}>
                  {selGardens.includes(g) ? '✓ ' : ''}{g}
                </span>
              ))}
              {selGardens.length > 0 && (
                <span onClick={() => setSelGardens([])} style={{ padding:'3px 10px', borderRadius:20, fontSize:11, cursor:'pointer', color:'#c0392b', border:'1.5px solid #c0392b' }}>✕ Clear</span>
              )}
            </div>
          </div>

          {/* Skip + AI options */}
          <div style={{ display:'flex', alignItems:'center', gap:20, flexWrap:'wrap', marginBottom:14 }}>
            <label style={{ display:'flex', alignItems:'center', gap:8, fontSize:13, cursor:'pointer' }}>
              <input type="checkbox" checked={skipBlank} onChange={e => setSkipBlank(e.target.checked)} />
              Skip lots where last sale price is blank
            </label>
            <div style={{ display:'flex', alignItems:'center', gap:8, fontSize:13 }}>
              <span style={{ color:'#555', fontWeight:600 }}>AI Suggestion History:</span>
              <select value={aiWeeks} onChange={e => setAiWeeks(e.target.value)}
                style={{ padding:'5px 8px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13 }}>
                <option value="2">Last 2 weeks</option>
                <option value="4">Last 4 weeks</option>
              </select>
            </div>
          </div>

          <div style={{ display:'flex', gap:10, flexWrap:'wrap' }}>
            <Button onClick={runPreview} disabled={loading || !partyId || !saleNo} variant="primary">
              {loading ? '⏳ Loading…' : '🔍 Preview Lots'}
            </Button>
            {preview.length > 0 && (
              <Button onClick={runAI} disabled={aiLoading} variant="warning">
                {aiLoading ? '🤖 Thinking…' : `🤖 AI Suggest (${aiWeeks} weeks)`}
              </Button>
            )}
          </div>
        </>}
      </Card>

      {/* AI info */}
      {aiInfo && (
        <div style={{ background:'#eff6ff', border:'1px solid #bfdbfe', borderRadius:8, padding:'10px 16px', marginBottom:12, fontSize:13, color:'#1e40af', display:'flex', alignItems:'center', gap:8 }}>
          🤖 <b>AI ({aiInfo.method})</b> suggested prices for <b>{aiInfo.count}</b> lots using <b>{aiInfo.weeks} weeks</b> of history ({aiInfo.history} sold records found).
        </div>
      )}

      {/* PREVIEW TABLE */}
      {preview.length > 0 && (
        <Card>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:12 }}>
            <div>
              <h3 style={{ fontSize:15 }}>{preview.length} lots found</h3>
              <div style={{ fontSize:12, color:'#888', marginTop:2 }}>
                Active: <b style={{ color:'#1a7a4a' }}>{activeCount}</b> · Skipped: <b style={{ color:'#c0392b' }}>{skipCount}</b>
              </div>
            </div>
            <div style={{ display:'flex', gap:8 }}>
              <Button size="sm" variant="outline" onClick={() => setSkipped({})}>Un-skip All</Button>
              <Button onClick={save} disabled={saving || activeCount===0} variant="success">
                {saving ? 'Saving…' : `💾 Save ${activeCount} Markings`}
              </Button>
            </div>
          </div>

          <div style={{ overflowX:'auto' }}>
            <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
              <thead>
                <tr style={{ background:'#f0f4f8' }}>
                  {['Skip','Garden','Grade','Mark','Bags','Net Wt','Min ₹','Max ₹','Last ₹','Suggest ₹','Final Price ₹','Broker'].map(h => (
                    <th key={h} style={{ padding:'7px 8px', textAlign:'left', fontWeight:700, color:'#444', borderBottom:'2px solid #e2e8f0', whiteSpace:'nowrap' }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {preview.map((row, i) => {
                  const skip = !!skipped[row.catalogue_id];
                  return (
                    <tr key={row.catalogue_id} style={{ borderBottom:'1px solid #f0f4f8', background: skip?'#fff5f5':(i%2===0?'#fff':'#fafbfc'), opacity:skip?0.45:1 }}>
                      <td style={{ padding:'6px 8px' }}><input type="checkbox" checked={skip} onChange={() => toggleSkip(row.catalogue_id)} /></td>
                      <td style={{ padding:'6px 8px', fontWeight:600, color:'#1a3c5e' }}>{row.garden}</td>
                      <td style={{ padding:'6px 8px' }}><span style={{ background:'#dbeafe', color:'#1e40af', padding:'2px 7px', borderRadius:99, fontSize:11, fontWeight:700 }}>{row.grade}</span></td>
                      <td style={{ padding:'6px 8px', fontSize:11 }}>{row.mark}</td>
                      <td style={{ padding:'6px 8px' }}>{row.bags || '—'}</td>
                      <td style={{ padding:'6px 8px' }}>{row.net_wt || '—'}</td>
                      <td style={{ padding:'6px 8px', color:'#1a7a4a', fontWeight:600 }}>{row.min_last_price ? `₹${fmt(row.min_last_price)}` : '—'}</td>
                      <td style={{ padding:'6px 8px', color:'#c0392b', fontWeight:600 }}>{row.max_last_price ? `₹${fmt(row.max_last_price)}` : '—'}</td>
                      <td style={{ padding:'6px 8px', color:'#888' }}>{row.last_sale_price ? `₹${fmt(row.last_sale_price)}` : <span style={{ color:'#f59e0b' }}>blank</span>}</td>
                      <td style={{ padding:'6px 8px', color:'#0f766e', fontWeight:600 }}>{row.suggested_price ? `₹${fmt(row.suggested_price)}` : '—'}</td>
                      <td style={{ padding:'6px 8px' }}>
                        <div style={{ display:'flex', alignItems:'center', gap:3 }}>
                          <span style={{ fontSize:11, color:'#888' }}>₹</span>
                          <input type="number" value={prices[row.catalogue_id] || ''} disabled={skip}
                            onChange={e => setPrices(p => ({ ...p, [row.catalogue_id]: e.target.value }))}
                            style={{ width:75, padding:'4px 6px', border:'1.5px solid #cbd5e0', borderRadius:5, fontSize:12, fontFamily:'monospace' }} />
                        </div>
                      </td>
                      <td style={{ padding:'6px 8px', color:'#888', fontSize:11 }}>{row.broker || '—'}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}
